{"code": "from collections import defaultdict,Counter
import json,numpy as np
u=[r for r in load_lab() if r['family']=='univariate_regression' and not r.get('excluded')]; groups=defaultdict(list)
for r in u: groups[(r['set_id'],json.dumps(r['model'],sort_keys=True),json.dumps(r['loss'],sort_keys=True))].append(r)
pairs=[]
for g in groups.values():
 for a in g:
  if a['optimizer']['type'] not in ['Adam','AdamW'] or a['optimizer']['lr']*a['budget']['training_steps']<1 or a['width']<64 or a['depth']<2: continue
  for b in g:
   if b['optimizer']['type'] not in ['Adam','AdamW','Adagrad'] or b['optimizer']['lr']>=a['optimizer']['lr']: continue
   d=b['optimizer']['lr']*b['budget']['training_steps'] if b['optimizer']['type']!='Adagrad' else 2*b['optimizer']['lr']*np.sqrt(b['budget']['training_steps'])
   pairs.append((a,b,d))
print('pairs',len(pairs))
for ln in [0,1]:
 for band in [(0,.05),(.05,.1),(.1,.5),(.5,1)]:
  p=[(a,b,d) for a,b,d in pairs if (a['n_ln']>0)==bool(ln) and band[0]<=d<band[1]]
  print('LN',ln,'low delta',band,'n',len(p),'high wins',sum(a['mean']<b['mean'] for a,b,d in p),'ratio',np.median([a['mean']/b['mean'] for a,b,d in p]) if p else None)
print('0LN examples')
for a,b,d in pairs:
 if a['n_ln']==0: print(a['set_id'],a['depth'],a['width'],a['activation'],a['budget']['training_steps'],a['optimizer'],round(a['mean'],6),b['optimizer'],round(b['mean'],6),round(d,4))"}

